import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Button,
  Typography,
  CircularProgress,
  Box,
  Alert
} from '@mui/material';
import {
  CheckCircle as CheckCircleIcon
} from '@mui/icons-material';

const EmailSignInModal = ({ open, onClose, onEmailSubmit, onSuccess }) => {
  const [email, setEmail] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [verificationSent, setVerificationSent] = useState(false);

  useEffect(() => {
    if (!open) return;
    setError('');
    setVerificationSent(false);
    setEmail('');
  }, [open]);

  const handleEmailVerification = async (e) => {
    e.preventDefault();

    if (!email) {
      setError('Please enter your email address');
      return;
    }

    try {
      setIsSubmitting(true);
      setError('');

      const response = await fetch('/api/auth/send-verification-email', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.error || 'Failed to send verification email');
      }

      setVerificationSent(true);
      localStorage.setItem('pendingVerificationEmail', email);

      if (onEmailSubmit) await onEmailSubmit(email);
      if (onSuccess) onSuccess({ email });

    } catch (err) {
      setError(err.message || 'Failed to send verification email');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    setEmail('');
    setError('');
    setVerificationSent(false);
    onClose();
  };

  return (
      <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
        <DialogTitle>Sign In to Book an Appointment</DialogTitle>

        <form onSubmit={handleEmailVerification}>
          <DialogContent>
            {verificationSent ? (
                <Box textAlign="center" py={3}>
                  <CheckCircleIcon color="success" sx={{ fontSize: 60, mb: 2 }} />
                  <Typography variant="h6">Check Your Email</Typography>
                  <Typography variant="body1" sx={{ mt: 1 }}>
                    We sent a verification link to <strong>{email}</strong>.
                  </Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                    Click the link to continue booking your appointment.
                  </Typography>
                </Box>
            ) : (
                <>
                  <Typography variant="body1" gutterBottom>
                    Enter your email address to receive a secure sign-in link.
                  </Typography>

                  <TextField
                      autoFocus
                      margin="dense"
                      label="Email Address"
                      type="email"
                      fullWidth
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      disabled={isSubmitting}
                      sx={{ mt: 2 }}
                  />

                  {error && (
                      <Alert severity="error" sx={{ mt: 2 }}>
                        {error}
                      </Alert>
                  )}
                </>
            )}
          </DialogContent>

          <DialogActions>
            <Button onClick={handleClose} disabled={isSubmitting}>
              {verificationSent ? 'Close' : 'Cancel'}
            </Button>

            {!verificationSent && (
                <Button
                    type="submit"
                    variant="contained"
                    disabled={isSubmitting}
                >
                  {isSubmitting ? <CircularProgress size={22} /> : 'Send Verification Email'}
                </Button>
            )}
          </DialogActions>
        </form>
      </Dialog>
  );
};

export default EmailSignInModal;
